from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
docs=json.loads((ROOT/'corpus.json').read_text());report=json.loads((ROOT/'results.json').read_text())
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Amazon Developer Docs Recommendation Lab | Baseframe</title><style>
*{box-sizing:border-box}body{margin:0;background:#f8f7f4;color:#172330;font:17px/1.65 system-ui}header,main,footer{max-width:1080px;margin:auto;padding:26px}header{display:flex;flex-wrap:wrap;justify-content:space-between;gap:15px;border-bottom:1px solid #ccd4d8}a{color:#155a73;text-underline-offset:4px}h1{font-size:clamp(34px,5vw,58px);line-height:1.15;letter-spacing:-.035em}h2{font-size:28px;line-height:1.3;margin-top:38px}h3{font-size:22px;line-height:1.35}p{max-width:850px}.eyebrow{font-size:13px;text-transform:uppercase;letter-spacing:.1em;color:#576d76}.controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.full{grid-column:1/-1}label{display:block;font-weight:650;font-size:14px}input,select,button{font:inherit;border:1px solid #8b9fa8;border-radius:5px;padding:11px;background:white;color:#172330}input,select{width:100%}button{cursor:pointer}button.primary{background:#155a73;color:white}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.result{padding:22px 0;border-top:1px solid #c9d1d5}.meta{font-size:13px;color:#566b74}.result p{margin:12px 0}.reason{font-size:14px}pre{padding:20px;background:#e8edef;overflow:auto;font-size:14px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:12px;border:1px solid #ccd4d8;text-align:left}th{background:#e8edef}.tablewrap{overflow-x:auto}details{border-top:1px solid #ccd4d8;padding:16px 0}summary{cursor:pointer;font-weight:650}.notice{color:#536970}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #bd8c45;outline-offset:3px}footer{font-size:14px;border-top:1px solid #ccd4d8}@media(max-width:650px){header,main,footer{padding:20px}.controls{grid-template-columns:1fr}.actions button{flex:1}h1{margin:22px 0}}</style></head><body><header><a href="../../thebaseframe/">THE BASEFRAME</a><a href="../../learning-labs.html">Learning Labs</a></header><main><p class="eyebrow">Public Amazon Developer documentation · Independent project</p><h1>Recommend the next useful document.</h1><p>Explore content recommendations by developer task, platform, and audience. Compare lexical matching, TF-IDF vectors, and a hybrid ranker that adds reviewed metadata.</p><div class="actions"><a href="Amazon_Docs_Recommendation_Lab.zip" download>Download the runnable lab</a><a href="https://github.com/sharmiladas/sharmiladas.github.io/tree/main/labs/amazon-docs-recommendation-lab">Source and setup guide</a></div><p class="notice">Eight source-linked, Baseframe-authored summaries reviewed on October 14, 2026. No internal Amazon data, neural embeddings, or cloud model calls. This static demonstration ranks locally in your browser.</p>
<h2>Try a recommendation</h2><form id="form"><div class="controls"><div class="full"><label for="query">Developer task or question</label><input id="query" maxlength="2000" value="test IAP purchases without charging testers" required></div><div><label for="mode">Ranking method</label><select id="mode"><option value="hybrid">Hybrid vectors and metadata</option><option value="tfidf">TF-IDF cosine vectors</option><option value="lexical">Lexical overlap baseline</option></select></div><div><label for="platform">Platform filter</label><select id="platform"><option value="any">Any platform</option><option value="web">Web</option><option value="mobile">Mobile</option><option value="tv">TV sign-in</option><option value="fire-os">Fire OS</option><option value="vega">Vega OS</option></select></div><div><label for="audience">Audience</label><select id="audience"><option value="developer">Developer</option><option value="qa">QA</option><option value="architect">Architect</option><option value="product">Product</option></select></div></div><div class="actions"><button class="primary" type="submit">Recommend documents</button><button type="button" id="reset">Reset feedback</button></div></form><p id="status" role="status" aria-live="polite"></p><section id="results" aria-label="Recommended documents"></section>
<h2>What was measured</h2><p>Actual offline development run: eight queries, including two requests with no relevant label. Relevance labels are proposed learning judgments. Other useful documents may be unlabeled; precision is especially sensitive to this incomplete labeling.</p><div class="tablewrap"><table><thead><tr><th>Method</th><th>Precision@3</th><th>Recall@3</th><th>NDCG@3</th><th>MRR</th><th>Negative abstention</th></tr></thead><tbody id="metrics"></tbody></table></div><p class="meta">Ranking averages use six positive dev cases; negative abstention uses two cases. Fixed three-slot precision counts missing slots as nonrelevant. No production, conversion, or user-impact measurement is claimed.</p>
<h2>Build it in four weeks</h2><ol><li><strong>Sources and objectives:</strong> inspect the source pages, stage public HTML for review, and define platform, task, audience, and lifecycle metadata.</li><li><strong>Ranking:</strong> compare query and related-document matching across lexical, vector, and metadata approaches. Inspect why each result was returned.</li><li><strong>Evaluation:</strong> independently label candidate relevance, calibrate reviewers, inspect regressions, and preserve the topic-grouped test set.</li><li><strong>Serving and feedback:</strong> run the local API, test the browser UI, and design a consent-based pilot with task-completion measures and review owners.</li></ol>
<h2>Run the local API</h2><pre><code>python3 recommender.py recommend --query "configure login redirects"
python3 recommender.py evaluate --split dev
python3 tests.py
python3 recommender.py serve</code></pre><p>Open <code>http://127.0.0.1:8765</code> after starting the downloaded server. Its <code>POST /recommend</code> accepts a query or source_id. The hosted static page does not expose this API.</p>
<h2>Architecture and scope</h2><details open><summary>Vectors, tags, and recommendation algorithms</summary><p>TF-IDF uses term counts and corpus frequencies, then cosine similarity between normalized sparse vectors. It is a real vector baseline, not a learned semantic embedding. Hybrid scoring combines 75% cosine, 20% query/tag overlap, and a 5% audience match when content or tag terms overlap. Related-document discovery excludes the current document. All modes enforce platform, active status, and public visibility.</p></details><details><summary>Ingestion and content engineering</summary><p>The included ingestion script stages main article text and checksums from a single approved public URL or local HTML export. Human review is required before indexing. This demo uses concise original summaries and reviewed tags; it does not automatically scrape a portal or generate LLM metadata.</p></details><details><summary>Privacy, feedback, and maintenance</summary><p>Useful/not-useful counters are stored only in this browser. They do not identify users or change ranking. Reset feedback removes those counters. No credentials, purchase history, personal profiling, or server query logging is used. Production authorization, monitoring, a learned model, and an MCP adapter remain future extensions.</p></details><details><summary>Uncertainty and incorrect matches</summary><p>A nonzero score only means shared features. It does not certify relevance or make a technical claim correct. Generic words can produce weak matches; no-result checks are intentionally limited. Verify source guidance and platform applicability before implementing it.</p></details>
<h2>Source directory</h2><ul id="sources"></ul><p><a href="README.md">Full learning and implementation guide</a> · <a href="results.json">Detailed dev results</a> · <a href="cases.json">Evaluation cases</a></p></main><footer>© 2026 Sharmila Das · The Baseframe · Independent learning project using public documentation</footer><script>'''
js=r'''
const STOP=new Set('a an the i how do does can me my we what which where for to with of in on is are and or it through want before'.split(' '));
const tok=s=>(s.toLowerCase().match(/[a-z0-9]+/g)||[]).filter(t=>!STOP.has(t));
function counts(s){const c={};for(const t of tok(s))c[t]=(c[t]||0)+1;return c;}
function vec(c,idf){let v={},norm=0;for(const [t,n] of Object.entries(c))if(t in idf){v[t]=(1+Math.log(n))*idf[t];norm+=v[t]*v[t];}norm=Math.sqrt(norm);if(norm)for(const t in v)v[t]/=norm;return v;}
function rank(q,mode,platform,audience,exclude=null){const ds=DOCS.filter(d=>d.status==='active'&&d.visibility==='public'),cs=ds.map(d=>counts(d.title+' '+d.summary)),df={};for(const c of cs)for(const t in c)df[t]=(df[t]||0)+1;const idf={};for(const t in df)idf[t]=Math.log((1+ds.length)/(1+df[t]))+1;const qs=new Set(tok(q)),qv=vec(counts(q),idf),rs=[];ds.forEach((d,i)=>{if(d.id===exclude||(platform!=='any'&&!d.platforms.includes(platform)))return;const c=cs[i],terms=[...qs].filter(t=>t in c).sort(),tags=new Set(tok(d.tags.join(' '))),hits=[...qs].filter(t=>tags.has(t)).sort(),dv=vec(c,idf);let cos=0;for(const t in dv)cos+=(qv[t]||0)*dv[t];let score=mode==='lexical'?terms.length/Math.max(1,qs.size):mode==='tfidf'?cos:.75*cos+.2*hits.length/Math.max(1,qs.size)+(d.audiences.includes(audience)&&(cos>0||hits.length)? .05:0);score=Math.round(score*1e6)/1e6;if(score>0)rs.push({...d,score,terms,hits});});return rs.sort((a,b)=>b.score-a.score||(a.id<b.id?-1:a.id>b.id?1:0)).slice(0,3);}
const el=id=>document.getElementById(id),node=(tag,text)=>{let n=document.createElement(tag);n.textContent=text;return n;};
let feedback={};try{feedback=JSON.parse(localStorage.getItem('baseframe-recommend-feedback-v1')||'{}');}catch(e){}
function display(q,exclude=null){const started=performance.now(),rs=rank(q,el('mode').value,el('platform').value,el('audience').value,exclude);el('results').replaceChildren();el('status').textContent=rs.length+' recommendations · '+(performance.now()-started).toFixed(2)+' ms local ranking'+(exclude?' · current page excluded':'');if(!rs.length)el('results').append(node('p','No matching documents in this small corpus. Try a documented task or broaden the platform filter.'));for(const d of rs){let a=node('article','');a.className='result';let h=node('h3',''),link=node('a',d.title);link.href=d.url;link.target='_blank';link.rel='noopener';h.append(link);a.append(h,node('p',d.summary));let meta=node('p',d.platforms.join(', ')+' · '+d.stage+' · source reviewed '+d.verified_at);meta.className='meta';a.append(meta);let why=node('p','Score '+d.score.toFixed(3)+' · content terms: '+(d.terms.join(', ')||'none')+' · tag terms: '+(d.hits.join(', ')||'none'));why.className='reason';a.append(why);let actions=node('div','');actions.className='actions';let rel=node('button','Find related documents');rel.type='button';rel.onclick=()=>{el('query').value=d.title+' '+d.summary;display(el('query').value,d.id);};actions.append(rel);for(const kind of ['Useful','Not useful']){let b=node('button',kind);b.type='button';b.onclick=()=>{let k=d.id+':'+kind;feedback[k]=(feedback[k]||0)+1;try{localStorage.setItem('baseframe-recommend-feedback-v1',JSON.stringify(feedback));el('status').textContent='Feedback saved in this browser only: '+kind+' ('+feedback[k]+')';}catch(e){el('status').textContent='Local storage is unavailable; feedback was not saved.'}};actions.append(b);}a.append(actions);el('results').append(a);}}
el('form').onsubmit=e=>{e.preventDefault();display(el('query').value)};el('reset').onclick=()=>{feedback={};try{localStorage.removeItem('baseframe-recommend-feedback-v1');el('status').textContent='Local feedback cleared.';}catch(e){el('status').textContent='Local storage unavailable.'}};
for(const [method,m] of Object.entries(REPORT.variants)){let row=node('tr','');row.append(node('th',method));for(const key of ['precision_at_3','recall_at_3','ndcg_at_3','mrr','negative_abstention_rate'])row.append(node('td',m[key]===null?'Not measured':m[key].toFixed(3)));el('metrics').append(row);}
for(const d of DOCS){let li=node('li',''),a=node('a',d.title);a.href=d.url;a.target='_blank';a.rel='noopener';li.append(a);el('sources').append(li);}display(el('query').value);
'''
payload='const DOCS='+json.dumps(docs).replace('<','\\u003c')+';const REPORT='+json.dumps(report).replace('<','\\u003c')+';'
(ROOT/'index.html').write_text(head+payload+js+'</script></body></html>')
print('Built self-contained interactive demo')
